class GpsDialogService{static $inject=["$mdDialog","DispatchData","toastrService"];constructor($mdDialog,DispatchData,toastrService){this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.toastrService=toastrService}getDeliveryLocation(currentJob){return currentJob.deliveryLongitude?{lat:currentJob.deliveryLatitude,long:currentJob.deliveryLongitude}:{lat:"",long:""}}getPickupLocation(currentJob){return currentJob.pickUpLongitude?{lat:currentJob.pickUpLatitude,long:currentJob.pickUpLongitude}:{lat:"",long:""}}showDialog(event,currentJob,field){function GpsDialogController($scope,$timeout,$mdDialog,NgMap,currentJob,addressDetails,suburbOptions){$timeout(()=>{$scope.mapDisplay=true},500);const findSuburbByDistrict=district=>{let lowerCaseDistrict=district.toLowerCase();return suburbOptions.find(localSuburb=>localSuburb.text.toLowerCase()===lowerCaseDistrict||localSuburb.alias&&localSuburb.alias.toLowerCase()===lowerCaseDistrict)};const transformSuggestions=data=>data.suggestions.map(obj=>({id:obj.locationId,text:obj.label.split(", ").reverse().join(", ")}));NgMap.getMap().then(map=>{console.log("Loading Map!");$scope.map=map;$scope.marker=map.markers[0];$scope.addressSearchAutocomplete(addressDetails.address)});$scope.title="Update Address and GPS";$scope.addressDetails=addressDetails;$scope.ourSuburbSearchText="";$scope.addressSearchText="";$scope.ourSuburbSelectedItem=findSuburbByDistrict(addressDetails.suburb);$scope.ourSuburbSearch=function(query){return query?suburbOptions.filter(suburb=>suburb.text.toLowerCase().indexOf(query.toLowerCase())!==-1):suburbOptions};$scope.addressSearchAutocomplete=function(text){try{return this.DispatchData.autocompleteAddressSearch(text).then(data=>{return transformSuggestions(data)})}catch(error){this.toastrService.showErrorToast(error.message)}};$scope.addressSearchItemSelected=function(item){try{this.DispatchData.getGeoCodeInformation(item).then(data=>{const returnedLocation=data.Response.View[0].Result[0].Location;console.log("Suburb = "+returnedLocation.Address.District);console.log("PostCode = "+returnedLocation.Address.PostalCode);const mappedSub=findSuburbByDistrict(returnedLocation.Address.District);if(mappedSub!==undefined){console.log(mappedSub);$scope.addressDetails.ourSuburbSelectedItem=mappedSub}else{$scope.addressDetails.ourSuburbSelectedItem=null;this.toastrService.showWarningToast("Matching suburb could not be found from this address."+"Please select manually.")}$scope.addressDetails.filledAddress=returnedLocation.Address.Label;$scope.addressDetails.lat=returnedLocation.DisplayPosition.Latitude;$scope.addressDetails.long=returnedLocation.DisplayPosition.Longitude;$scope.addressDetails.address=returnedLocation.Address.Label;$scope.addressDetails.suburb=returnedLocation.Address.District;$scope.addressDetails.postCode=returnedLocation.Address.PostalCode;const latLng=new google.maps.LatLng(returnedLocation.DisplayPosition.Latitude,returnedLocation.DisplayPosition.Longitude);$scope.map.setCenter(latLng);$scope.marker.setPosition(latLng)})}catch(error){this.toastrService.showErrorToast(error.message)}};function rateJob(job){const pedal=job.fromSuburbID===1&&job.toSuburbID===1||job.fromSuburbID===112&&job.toSuburbID===112||job.fromSuburbID===480&&job.toSuburbID===480;if(job.size.id===4&&(job.speedID===41||job.speedID===42||job.speedID===43||job.speedID===44||job.speedID===46||job.speedID===51||job.speedID===52||job.speedID===124||job.speedID===125||job.speedID===150||job.speedID===151||job.speedID===152)){return this.DispatchData.getTruckItemsSummary(job.id,job.truckWeightLimit).then(itemSummary=>{return this.DispatchData.rateTruckJob(job.clientID,job.fromSuburbID,job.toSuburbID,itemSummary.weight,job.size.id,job.speedID,itemSummary.quantity,job.booked,itemSummary.pickUp,itemSummary.dropOff,job.privateRes,itemSummary.overSize,itemSummary.overWeight,itemSummary.dgClass,job.truckStartTime||moment().format("YYYY-MM-DDThh:mm:ss"),job.truckHours||2)})}else{return this.DispatchData.rateJob(job.clientID,job.fromSuburbID,job.toSuburbID,job.speedID,pedal,job.van,job.return,job.weight,job.size.id,true,job.direct,job.acceptedJobTypeID,job.ourRef||"",job.refA||"",job.refB||"",job.items,job.booked)}}$scope.submit=function(addressDetails){try{const job=currentJob;if($scope.ourSuburbSelectedItem.id!==undefined){addressDetails.our_suburb=$scope.ourSuburbSelectedItem.id}if(addressDetails.our_suburb===undefined){const alert=$mdDialog.alert({title:"Courier Suburb Not Mapped",textContent:"You must pick one of our suburbs to map this address to",ok:"Close"});$mdDialog.show(alert).then(_=>$mdDialog.close())}if(field==="toAddress"){job.toAddress=(addressDetails.extras||"").length>1?addressDetails.extras+","+addressDetails.address:addressDetails.address;if(job.bulkJob){return this.DispatchData.updateBulkDeliveryAddress(job.id,addressDetails.suburb,addressDetails.postCode,job.toAddress,addressDetails.lat,addressDetails.long,FirstName).then(()=>{$mdDialog.hide();this.toastrService.showSuccessToast("Address successfully updated")})}job.toSuburbID=parseInt(addressDetails.our_suburb)}else{job.fromAddress=(addressDetails.extras||"").length>1?addressDetails.extras+","+addressDetails.address:addressDetails.address;if(job.bulkJob){return this.DispatchData.updateBulkPickupAddress(job.id,addressDetails.suburb,addressDetails.postCode,job.fromAddress,addressDetails.lat,addressDetails.long,FirstName).then(()=>{$mdDialog.hide();this.toastrService.showSuccessToast("Address successfully updated")})}job.fromSuburbID=parseInt(addressDetails.our_suburb)}const pedal=job.fromSuburbID===1&&job.toSuburbID===1||job.fromSuburbID===112&&job.toSuburbID===112||job.fromSuburbID===480&&job.toSuburbID===480;return rateJob(job).then(rate=>{const callData={call:"updateJobData",addressField:field,lat:addressDetails.lat,long:addressDetails.long,fromSuburbId:job.fromSuburbID,toSuburbId:job.toSuburbID,fromAddress:job.fromAddress,toAddress:job.toAddress,rate:rate,jobID:job.id,CBD:pedal};console.log(callData);if(field==="toAddress"){this.DispatchData.updateDeliveryAddress(callData.jobID,callData.toSuburbId,callData.toAddress,callData.lat,callData.long,callData.CBD,Number(callData.rate.replace(/[^0-9.-]+/g,"")),FirstName,job.preBook).then(()=>{$mdDialog.hide();this.toastrService.showSuccessToast("Address successfully updated")})}else{return this.DispatchData.updatePickupAddress(callData.jobID,callData.fromSuburbId,callData.fromAddress,callData.lat,callData.long,callData.CBD,Number(callData.rate.replace(/[^0-9.-]+/g,"")),FirstName,job.preBook).then(()=>{$mdDialog.hide();this.toastrService.showSuccessToast("Address successfully updated")})}})}catch(error){this.toastrService.showErrorToast(error.message)}};$scope.copyGpsAddress=address=>$scope.addressSearchText=address;$scope.moveMarker=function(event){$scope.addressDetails.lat=event.latLng.lat();$scope.addressDetails.long=event.latLng.lng();$scope.$apply()};$scope.markerDragend=function(event){const location=event.latLng;try{this.DispatchData.retrieveAddresses(location.lat(),location.lng()).then(data=>{const returnedLocation=data.Response.View[0].Result[0].Location;$scope.addressDetails.address=returnedLocation.Address.Label;$scope.addressDetails.suburb=returnedLocation.Address.District;$scope.addressDetails.lat=returnedLocation.DisplayPosition.Latitude;$scope.addressDetails.long=returnedLocation.DisplayPosition.Longitude;console.log("Suburb = "+returnedLocation.Address.District);console.log("PostCode = "+returnedLocation.Address.PostalCode);const mappedSub=suburbOptions.find(obj=>obj.text===returnedLocation.Address.District||obj.alias===returnedLocation.Address.District);if(mappedSub!==undefined){console.log(mappedSub);$scope.ourSuburbSelectedItem=mappedSub}else{$scope.ourSuburbSelectedItem=null}})}catch(error){this.toastrService.showErrorToast(error.message)}};$scope.placeChanged=function(place){try{$scope.addressDetailsa.lat=place.geometry.location.lat();$scope.addressDetails.long=place.geometry.location.lng();if(place.address_components.find(x=>x.types[0]==="postal_code")){$scope.addressDetails.postCode=place.address_components.find(x=>x.types[0]==="postal_code").long_name}$scope.map.setCenter(place.geometry.location)}catch(error){this.toastrService.showErrorToast(error.message)}};$scope.cancel=()=>$mdDialog.cancel()}const location=field==="toAddress"?this.getDeliveryLocation(currentJob):this.getPickupLocation(currentJob);const{lat,long}=location;const suburbText=field==="toAddress"?currentJob.toSuburbName:currentJob.fromSuburbName;this.$mdDialog.show({parent:angular.element(document.body),targetEvent:event,templateUrl:"app/components/home/tpls/gpsForm.tpl",clickOutsideToClose:false,fullscreen:true,locals:{currentJob:currentJob,addressDetails:{address:currentJob[field],lat:lat,long:long,suburb:suburbText,postCode:currentJob.postCode},suburbOptions:currentJob.pickSuburbs},controller:GpsDialogController}).then(()=>{this.$mdDialog.cancel();console.log("Dialog Closed!")})}}angular.module("uDispatch").service("gpsDialogService",GpsDialogService);